insert  into `server_req`(`id`,`facility_name`,`is_active`,`show_in_tab`,`user_id`,`terms_when_signed`,`facility_address`,`facility_contact`,`facility_email`,`requester_name`,`requester_department`,`requester_designation`,`requester_con_number`,`requester_email`,`focal_name`,`focal_designation`,`focal_con_number`,`focal_email`,`alt_focal_name`,`alt_focal_designation`,`alt_focal_con_number`,`alt_focal_email`,`developer_name`,`developer_address`,`developer_con_number`,`developer_email`,`purpose_of_server`,`expected_benefit`,`resource_needs`,`frontend_info`,`backend_info`,`db_info`,`others_info`,`server_type`,`server_type_other_details`,`hosted_service`,`hosted_service_other_details`,`processor_required`,`processor_required_other_details`,`memory_ram`,`memory_ram_other_details`,`space_for_os`,`space_for_os_other_details`,`additional_space`,`additional_space_other_details`,`raid_configuration`,`os_name`,`os_version`,`license_provided_by`,`additional_software_packages`,`domain_name`,`ssl_provider`,`ssl_cost`,`network_access_required`,`firewal_port_1`,`firewal_purpose_1`,`firewal_port_2`,`firewal_purpose_2`,`firewal_port_3`,`firewal_purpose_3`,`backup_space_required`,`backup_performed_by`,`backup_frequency`,`accept_check_bottom`,`rquester_full_name`,`requester_signature`,`request_date`,`accept_check1`,`backup_space_required_other_details`,`request_status`,`approver1_name`,`approver2_name`,`approver3_name`,`approver4_name`,`server_name_id`,`deployment_team`,`deployment_timeline`,`server_assigned_details`,`deployment_date`,`application_name`,`project_end_date`,`renew_check`,`software_license_info`,`os_license_info`,`db_license_info`,`others_license_info`,`proxy_ip_name`,`sub_domain_name`) values (3,'e-Health, MIS DGHS',1,0,98,'Without DGHS’s management’s prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\nAll required information must be filled up by the requester of the server.<br/>\nServer deployment will be done after approval from DGHS MIS authority.<br/>\nThe requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\nAll applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\nThe service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\nThe service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\nRequired patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\nIn the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\nThe service owner must maintain an independent backup locally of the application, database (dump) for redundancy and recovery in unforeseen situations.<br/>\nIf the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nAcknowledgment and Acceptance<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','Mohakhali Dhaka','01322858216','sofordar@mis.dghs.gov.bd','Dr. Md Zahidul Islam','e-Health','DPM','01322858216','sofordar@mis.dghs.gov.bd','Dr. Md Zahidul Islam','DPM','01322858216','sofordar@mis.dghs.gov.bd','Dr. Md Zahidul Islam','DPM','01322858216','sofordar@mis.dghs.gov.bd','Abu Jobayer Bin Ali','MIS DGHS, Mohakhali, Dhaka','01718542900','jobayer.sd.ntp@gmail.com','Hosting','CI/CD implementation','Initial Assumption','N/A','N/A','N/A','N/A','Production','','Application','','8 cores','','16 GB','','50 GB','','Other','0','RAID 0','Ubuntu','22.04','Open Source','N/A','','MIS','Open source','Internet Access','','','','','','','50 GB','MIS','Daily','accept','Dr. Md. Zahidul Islam','1625005159_1753607559.jpg','2025-07-27','accept','','Approved & Deployed','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy','Zulfiker Ali','dghs-ci/cd01','NNS Solution ltd','30/07/2025 \n3.00PM',' Server name: dghs-ci/cd01\nServer IP : 172.16.18.141\nOS : Ubuntu 22.04\nCPU : 4\nMemory : 8 G\nStorage :55 GB\nUsername; root/mishealth\n','2025-07-30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(4,'MIS, DGHS',1,0,99,'Without DGHS’s management’s prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\nAll required information must be filled up by the requester of the server.<br/>\nServer deployment will be done after approval from DGHS MIS authority.<br/>\nThe requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\nAll applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\nThe service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\nThe service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\nRequired patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\nIn the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\nThe service owner must maintain an independent backup locally of the application, database (dump) for redundancy and recovery in unforeseen situations.<br/>\nIf the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nAcknowledgment and Acceptance<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','TB Gate, Mohakhali, Dhaka','01711731891','system.analyst@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','MIS, DGHS','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Md. Akber Hossain','Programmer','01701248094','programmer2@mis.dghs.gov.bd','MIS, DGHS','TB Gate, Mohakhali, Dhaka','01711731891','system.analyst@mis.dghs.gov.bd','Testing different systems\' life cycle','Testing different systems\' life cycle','Testing different systems\' life cycle','N/A','N/A','N/A','N/A','Production','','Application','','4 cores','','8 GB','','50 GB','','Other','N/A','RAID 0','Ubuntu','22.04','Open Source','N/A','N/A','MIS','Open source','Internet Access','','','','','','','Other','MIS','Monthly','accept','Muhammed Ziaul Alam Chowdhury','2000402826_1753610398.png','2025-07-27','accept','N/A','Approved & Deployed','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy','Zulfiker Ali','dghs-ci/cd02','NNS Solution ltd','30/07/2025','Server name: dghs-ci/cd02\nServer IP : 172.16.18.142\nOS : Ubuntu 22.04\nCPU : 8\nMemory : 16 G\nStorage :55 GB\nUsername; root/mishealth','2025-07-30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(5,'MIS, DGHS\n',1,0,99,'Without DGHS’s management’s prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\nAll required information must be filled up by the requester of the server.<br/>\nServer deployment will be done after approval from DGHS MIS authority.<br/>\nThe requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\nAll applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\nThe service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\nThe service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\nRequired patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\nIn the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\nThe service owner must maintain an independent backup locally of the application, database (dump) for redundancy and recovery in unforeseen situations.<br/>\nIf the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nAcknowledgment and Acceptance<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','TB Gate, Mohakhali, Dhaka\n','01711731891','info@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','MIS, DGHS','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Md. Akber Hossain','Programmer','01701248094','programmer2@mis.dghs.gov.bd','MIS, DGHS','TB Gate, Mohakhali, Dhaka\n','01711731891','system.analyst@mis.dghs.gov.bd','Testing different systems\' life cycle','Testing different systems\' life cycle','Testing different systems\' life cycle','N/A','N/A','N/A','N/A','Production','','Application','','4 cores','','8 GB','','50 GB','','Other','N/A','RAID 0','Ubuntu','22.04','Open Source','N/A','N/A','MIS','Open source','Internet Access','N/A','N/A','','','','','Other','MIS','Monthly','accept','Muhammed Ziaul Alam Chowdhury','2000402826_1753610398.png','2025-07-31','accept','N/A','Approved & Deployed','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy','Zulfiker Ali','life cycle test','NNS Solution ltd','03/08/2025','172.16.18.143','2025-08-03',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL),(6,'MIS,DGHS',1,0,99,'•	Without DGHSs managements prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\n•	All required information must be filled up by the requester of the server.<br/>\n•	Server deployment will be done after approval from DGHS MIS authority.<br/>\n•	The requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\n•	All applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\n•	The service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\n•	The service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\n•	Required patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\n•	In the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\n•	DGHS will perform centralized backup (minimum 24 hour interval) of data from the above specified location only and the data will be retained as per retention policy.<br/>\n•	For DB backup, Database Administrator is fully responsible for storing the dump files into the defined backup directory as per above specified RPO time interval.<br/>\n•	RPO (Recovery Point Objective) is the maximum time of data loss that can tolerate.<br/>\n•	Basic installation of OS will be done by DGHS. In case of any specific package installation/configuration will be required, then DGHS will provide console login to the server so that application vendor can install OS/packages of their own.<br/>\n•	Each deployed system must undergo an half yearly review and renewal process. The service owner must submit a renewal request. Failure to renew within the stipulated period may result in suspension or decommissioning of the system.<br/>\n•	If the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','TB Gate, Mohakhali, Dhaka','01711731891','info@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','MIS, DGHS','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Kazi Fabliha Tasnim','Maintenance Engineer','01722531322','me@mis.dghs.gov.bd','Younus Jamil Rana','Assistant Maintenance Engineer','01746605604','ame@mis.dghs.gov.bd','MIS Team ','TB Gate, Mohakhali, Dhaka','01722531322','me@mis.dghs.gov.bd','Deploying and Testing Log Server ','Collecting and monitoring different Logs from various sources','Collecting Logs from various sources','N/A','N?A','N/A','N/A','Development','','Other','','4 cores','','8 GB','','50 GB','','100 GB','','RAID 0','Ubuntu','24.04','Open Source','N/A','N/A','MIS','Open source','Internet Access','N/A','N/A','','','','','50 GB','MIS','Monthly','accept','Muhammed Ziaul Alam Chowdhury','2000402826_1753610398.png','2025-07-31','accept','','Approved','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy',NULL,NULL,NULL,NULL,NULL,NULL,'Test Log Server','2030-12-31','Yes','N/A','N/A','N/A','N/A',NULL,NULL),(7,'MIS,DGHS\n',1,0,99,'•	Without DGHSs managements prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\n•	All required information must be filled up by the requester of the server.<br/>\n•	Server deployment will be done after approval from DGHS MIS authority.<br/>\n•	The requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\n•	All applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\n•	The service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\n•	The service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\n•	Required patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\n•	In the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\n•	DGHS will perform centralized backup (minimum 24 hour interval) of data from the above specified location only and the data will be retained as per retention policy.<br/>\n•	For DB backup, Database Administrator is fully responsible for storing the dump files into the defined backup directory as per above specified RPO time interval.<br/>\n•	RPO (Recovery Point Objective) is the maximum time of data loss that can tolerate.<br/>\n•	Basic installation of OS will be done by DGHS. In case of any specific package installation/configuration will be required, then DGHS will provide console login to the server so that application vendor can install OS/packages of their own.<br/>\n•	Each deployed system must undergo an half yearly review and renewal process. The service owner must submit a renewal request. Failure to renew within the stipulated period may result in suspension or decommissioning of the system.<br/>\n•	If the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','TB Gate, Mohakhali, Dhaka','01711731891','info@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','TB Gate, Mohakhali, Dhaka','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Kazi Fabliha Tasnim','Maintenance Engineer','01722531322','me@mis.dghs.gov.bd','Younus Jamil Rana','Assistant Maintenance Engineer','01746605604','ame@mis.dghs.gov.bd','MIS, DGHS','TB Gate, Mohakhali, Dhaka','01722531322','me@mis.dghs.gov.bd','Real-time monitoring of logs, diagnose problems, analyzing logs from different sources etc\n','Centralized visibility, enhanced security monitoring, compliance support, faster troubleshooting, improved incident response, and reduced operational costs through efficient log management.','To ensure reliable log processing, storage, and system stability for effective monitoring, troubleshooting, and compliance.','N/A','N/A','N/A','N/A','Production','','Other','','4 cores','','16 GB','','Other','200','Other','N/A','RAID 0','Ubuntu','24.04','Open Source','N/A','N/A','MIS','Open source','Internet Access','N/A','N/A','','','','','50 GB','MIS','Daily','accept','Muhammed Ziaul Alam Chowdhury','2000402826_1753610398.png','2025-07-31','accept','','Approved','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy',NULL,NULL,NULL,NULL,NULL,NULL,'DC Log Server','2030-12-31','Yes','N/A','N/A','N/A','N/A',NULL,NULL),(8,'MIS,DGHS',1,0,99,'•	Without DGHSs managements prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\n•	All required information must be filled up by the requester of the server.<br/>\n•	Server deployment will be done after approval from DGHS MIS authority.<br/>\n•	The requester must ensure that their software or web application does not contain any malicious code, vulnerabilities, or defects that could compromise the security, stability, or performance of the server or the network.<br/>\n•	All applications deployed on the server must comply with established national and international industry security standards and best practices.<br/>\n•	The service owner will be responsible for any harm caused by their software or web application, including data breaches, service disruptions, or unauthorized access resulting from the application.<br/>\n•	The service owner must test their software for risks/vulnerabilities before deployment and a report will be submitted to MIS.<br/>\n•	Required patch update or anything needful to ensure cyber security must be done by developer or organization.<br/>\n•	In the case of API integration, the service owner must comply with all terms and conditions as outlined in the API contract.<br/>\n•	DGHS will perform centralized backup (minimum 24 hour interval) of data from the above specified location only and the data will be retained as per retention policy.<br/>\n•	For DB backup, Database Administrator is fully responsible for storing the dump files into the defined backup directory as per above specified RPO time interval.<br/>\n•	RPO (Recovery Point Objective) is the maximum time of data loss that can tolerate.<br/>\n•	Basic installation of OS will be done by DGHS. In case of any specific package installation/configuration will be required, then DGHS will provide console login to the server so that application vendor can install OS/packages of their own.<br/>\n•	Each deployed system must undergo an half yearly review and renewal process. The service owner must submit a renewal request. Failure to renew within the stipulated period may result in suspension or decommissioning of the system.<br/>\n•	If the system is no longer in use for any reason, then the system owner will inform to MIS, DGHS.<br/>\nBy signing below, the service owner agrees to the above terms and confirms compliance with the stated conditions.<br/>\n            ','TB Gate, Mohakhali, Dhaka','01711731891','info@mis.dghs.gov.bd','Muhammed Ziaul Alam Chowdhury','TB Gate, Mohakhali, Dhaka','System Analyst','01711731891','system.analyst@mis.dghs.gov.bd','Kazi Fabliha Tasnim','Maintenance Engineer','01722531322','me@mis.dghs.gov.bd','Younus Jamil Rana','Assistant Maintenance Engineer','01746605604','ame@mis.dghs.gov.bd','MIS Team','TB Gate, Mohakhali, Dhaka','01722531322','me@mis.dghs.gov.bd','Real-time monitoring of logs, diagnose problems, analyzing logs from different sources etc','Centralized visibility, enhanced security monitoring, compliance support, faster troubleshooting, improved incident response, and reduced operational costs through efficient log management.','To ensure reliable log processing, storage, and system stability for effective monitoring, troubleshooting, and compliance.','N/A','N/A','N/A','N/A','Production','','Other','','4 cores','','8 GB','','50 GB','','100 GB','','RAID 0','Ubuntu','24.04','Open Source','N/A','N/A','MIS','Open source','Internet Access','N/A','N/A','','','','','50 GB','MIS','Daily','accept','Muhammed Ziaul Alam Chowdhury','2000402826_1753610398.png','2025-08-03','accept','','Approved','Younus Jamil Rana','Kazi Fabliha Tasnim','Sukhendu Shekhor Roy',NULL,NULL,NULL,NULL,NULL,NULL,'Log Client','2030-12-31','Yes','N/A','N/A','N/A','N/A',NULL,NULL),(9,'NCCBCST, Bangladesh Medical University',1,0,100,'•	Without DGHSs managements prior written approval Data Center management personnel of DGHS will not provide management access to the server from the internet.<br/>\n•	All required information must be filled up by the requester of the server.<br/>\n•	Server deployment will be done after approval from DGHS MIS 