CREATE TABLE `user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agency_id` int(11) DEFAULT NULL,
  `psource_id` int(11) DEFAULT NULL,
  `first_name` varchar(50) DEFAULT NULL,
  `last_name` varchar(50) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(14) DEFAULT NULL,
  `user_id` varchar(50) DEFAULT NULL,
  `password` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `demand_status` varchar(20) DEFAULT NULL,
  `edemand` varchar(20) DEFAULT NULL,
  `equipment_brands` varchar(20) DEFAULT NULL,
  `equipment_status` varchar(20) DEFAULT NULL,
  `equipmentr_info` varchar(20) DEFAULT NULL,
  `equipments` varchar(20) DEFAULT NULL,
  `providers` varchar(20) DEFAULT NULL,
  `releases` varchar(20) DEFAULT NULL,
  `user` varchar(20) DEFAULT NULL,
  `settings` varchar(20) DEFAULT NULL,
  `report` varchar(20) DEFAULT NULL,
  `facilities` varchar(20) DEFAULT NULL,
  `psource` varchar(50) DEFAULT NULL,
  `agency` varchar(50) DEFAULT NULL,
  `report_cc` varchar(20) DEFAULT NULL,
  `purchase` varchar(20) DEFAULT NULL,
  `sale` varchar(20) DEFAULT NULL,
  `supplier` varchar(255) DEFAULT NULL,
  `customer` varchar(255) DEFAULT NULL,
  `equipments_type` varchar(255) DEFAULT NULL,
  `op` varchar(255) DEFAULT NULL,
  `purchase_report` int(11) DEFAULT NULL,
  `sale_report` int(11) DEFAULT NULL,
  `private_hospital` varchar(50) DEFAULT NULL,
  `ntpreport` varchar(50) DEFAULT NULL,
  `dengue_dhis2` varchar(50) DEFAULT NULL,
  `server_req` varchar(255) DEFAULT NULL,
  `redirect_url` varchar(255) DEFAULT NULL,
  `server_req_app1` varchar(255) DEFAULT NULL,
  `server_req_app2` varchar(255) DEFAULT NULL,
  `server_req_app3` varchar(255) DEFAULT NULL,
  `server_req_app4` varchar(255) DEFAULT NULL,
  `user_type_server` int(11) DEFAULT NULL,
  `user_server` varchar(255) DEFAULT NULL,
  `signature` varchar(255) DEFAULT NULL,
  `designation` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8;
